init_define_SG_BUILD();
var PERSONAL_SCRIPTURES = "Library/Scriptures";
var CANONICAL_SCRIPTURES = "AI Library/01 Scriptures/Canonical";
function chapterStudyPath(title, canonicalPath) {
  const inside = canonicalPath?.startsWith(`${CANONICAL_SCRIPTURES}/`) ? canonicalPath.slice(CANONICAL_SCRIPTURES.length + 1).split("/").slice(0, -1).join("/") : "";
  return [PERSONAL_SCRIPTURES, inside, `${title} - My Notes.md`].filter(Boolean).join("/");
}
function chapterStudyTemplate(title) {
  const slug = title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  return `---
ownership: personal
mutable: user
content_type: personal-notes
slug: ${slug}
cssclasses:
- sg-personal
---

# ${title} \u2014 My Study

> [!tip]- Views & navigation
> [[${title}|\u{1F4DC} Scripture only]] \xB7 [[${title} - Study Guide|\u{1F4D6} Study guide]] \xB7 [[Study Hub|\u{1F3E0} Study Hub]]

![[${title}]]

## \u270D\uFE0F My Notes
`;
}
async function openChapterStudy(host, title) {
  const existing = host.companion(title);
  if (existing) {
    await host.open(existing);
    return "opened";
  }
  if (!host.canonical(title)) await host.ensureLocal(title);
  const canonical = host.canonical(title);
  if (!canonical) {
    if (!host.signedIn()) {
      host.connect(`Connect to the family library to read ${title}. It takes one invite code.`);
      return "connect";
    }
    host.notify(`${title} hasn't downloaded yet. Check the family server connection and try again.`);
    return "unavailable";
  }
  const path = chapterStudyPath(title, canonical);
  try {
    await host.create(path, chapterStudyTemplate(title));
  } catch {
    if (!host.companion(title)) {
      await host.open(title);
      return "opened";
    }
  }
  await host.open(host.companion(title) ?? title);
  return "created";
}

