// src/study/atlas/math.ts
init_define_SG_BUILD();
function distanceKm(a2, b) {
  const r = Math.PI / 180, p = a2[1] * r, q = b[1] * r;
  const h = Math.sin((q - p) / 2) ** 2 + Math.cos(p) * Math.cos(q) * Math.sin((b[0] - a2[0]) * r / 2) ** 2;
  return 12742.0176 * Math.asin(Math.min(1, Math.sqrt(h)));
}
function projection(bounds) {
  const [w = -180, s = -60, e = 180, n = 80] = bounds;
  const cos = Math.cos((n + s) / 2 * Math.PI / 180);
  const scale = Math.min(920 / ((e - w) * cos), 550 / (n - s));
  return (p) => [
    500 + (p[0] - (w + e) / 2) * cos * scale,
    310 - (p[1] - (n + s) / 2) * scale
  ];
}

// src/study/atlas/settlement-distance.ts
init_define_SG_BUILD();
function settlementDistances(input) {
  const { centerKm: d, departureRadiusKm: a2, arrivalRadiusKm: b, centerAllowanceKm: u, routeFactor: f, kmPerDay: rate } = input;
  if (![d, a2, b, u, f, rate].every(Number.isFinite) || Math.min(d, a2, b, u) < 0 || f < 1 || rate <= 0) throw new RangeError("Invalid settlement distance inputs");
  const centers = [Math.max(0, d - u), d + u];
  const sum = a2 + b;
  function row(id, label2, straightKm) {
    return {
      id,
      label: label2,
      straightKm,
      routeKm: straightKm?.map((k) => k * f),
      days: straightKm?.map((k) => k * f / rate)
    };
  }
  return [
    row("centers", "Center to center", centers),
    row("facing", "Leave facing edge \u2192 reach facing edge", [Math.max(0, centers[0] - sum), Math.max(0, centers[1] - sum)]),
    // Triangle-inequality envelope for unspecified endpoints anywhere within the disks.
    // Gates are a subset: this envelope does not assert a gate exists at either extreme.
    row("unknown", "Departure / arrival point unknown", [Math.max(0, centers[0] - sum), centers[1] + sum]),
    // Collinear diameter crossing only applies when both circular cities remain disjoint.
    row("through", "Leave facing edge \u2192 cross arrival city", centers[0] >= sum ? [centers[0] - a2 + b, centers[1] - a2 + b] : null)
  ];
}

