    results.hidden = !valid;
    error.hidden = valid;
    if (!valid) return;
    results.replaceChildren();
    node("p", results, `Center separation: ${centerDistance.toFixed(2)} km. Assumed city diameters: ${(settings.departure * 2).toFixed(1)} km and ${(settings.arrival * 2).toFixed(1)} km.`);
    node("p", results, settings.includeLocation ? `Candidate-location allowance: \xB1${allowance} km in center separation, from the two editorial search radii combined. This is additional to city size and is not a statistical interval.` : "Candidate locations are held fixed. Only the endpoint and city-size assumptions below vary.");
    const table = node("table", results);
