  const reference = (file) => ["reference-copy", "references"].includes(String(app.metadataCache.getFileCache(file)?.frontmatter?.content_type)) || /^Reference\b/i.test(file.basename);
  const preparation = (file) => /\b(prepar(?:ation|e)|teacher.?s? guide|teaching notes|handout)\b/i.test(file.basename);
