// src/study/eventBackgrounds.ts
function eventBackgrounds(names) {
  return Object.entries(SCENE_OVERRIDES).flatMap(([slug, scene]) => {
    const match = /^(.+)-(\d+)$/.exec(slug);
    const book = match && BOOK_BY_SLUG.get(match[1]);
    const number = Number(match?.[2]);
    if (!book || number < 1 || number > book.chapters || !SCENE_CATALOG[scene]) return [];
    return [{
      slug,
      chapter: chapterTitle(book.slug, number),
      volume: book.volume,
      scene,
      name: names[scene] ?? scene,
      order: book.volumeSeq * 1e5 + book.bookSeq * 1e3 + number
    }];
  }).sort((a2, b) => a2.order - b.order);
}
function filterBackgrounds(rows, query) {
  const terms = query.toLowerCase().trim().split(/\s+/).filter(Boolean);
  return rows.filter((row) => terms.every((term) => `${row.chapter} ${row.volume} ${row.name}`.toLowerCase().includes(term)));
}
function renderEventBackgrounds(c2, rows, query, page, io) {
  const search = c2.createEl("input", { cls: "sg-nav-filter", attr: {
    type: "search",
    placeholder: "Search chapters or events\u2026",
    "aria-label": "Search event backgrounds"
  } });
  search.value = query;
  c2.createEl("p", { cls: "sg-event-help", text: "Chapters with assigned backgrounds. Tap a photo to inspect it, or open the chapter to read. Photos load as you browse." });
  const results = c2.createDiv();
  let disposePage = () => {
  };
  const render = () => {
    disposePage();
    results.empty();
    let disposed = false;
    const matches = filterBackgrounds(rows, query);
    const pageCount = Math.max(1, Math.ceil(matches.length / 12));
    page = Math.min(Math.max(0, page), pageCount - 1);
    io.page(page);
    results.createEl("p", { text: `${matches.length} chapters \xB7 ${new Set(matches.map((r) => r.scene)).size} backgrounds` });
    const grid = results.createDiv({ cls: "sg-nav-covers sg-event-grid" });
    const loaders = /* @__PURE__ */ new Map();
    const observer = typeof IntersectionObserver === "undefined" ? null : new IntersectionObserver((entries) => {
      for (const entry of entries) if (entry.isIntersecting) {
        loaders.get(entry.target)?.();
        observer?.unobserve(entry.target);
      }
    }, { rootMargin: "100px" });
    disposePage = () => {
      disposed = true;
      observer?.disconnect();
      loaders.clear();
    };
    for (const row of matches.slice(page * 12, (page + 1) * 12)) {
      const cell = grid.createDiv({ cls: "sg-event-cell" });
      const cover = cell.createEl("button", { cls: "sg-nav-cover sg-event-cover", attr: { "aria-label": `Preview ${row.name} \u2014 ${row.chapter}` } });
      const art = cover.createDiv({ cls: "sg-nav-cover-art" });
      const status = art.createSpan({ cls: "sg-event-status", text: "Photo preview" });
      cover.createDiv({ cls: "sg-nav-cover-label", text: row.chapter });
      cell.createDiv({ cls: "sg-event-scene-name", text: row.name });
      let loading = false;
      const load = async () => {
        if (disposed || loading) return;
        loading = true;
        status.setText("Loading photo\u2026");
        try {
          const url = await io.photo(row.scene, false);
          if (disposed) return;
          const img = art.createEl("img", { attr: { src: url, alt: row.name } });
          img.onerror = () => {
            img.remove();
            loading = false;
            status.setText("Photo unavailable \xB7 tap to retry");
          };
          status.setText("");
        } catch {
          if (!disposed) {
            loading = false;
            status.setText("Photo unavailable \xB7 tap to retry");
          }
        }
      };
      loaders.set(cover, () => void load());
      if (observer) observer.observe(cover);
      else void load();
      cover.onclick = () => {
        io.preview(row);
        if (!loading) void load();
      };
      cell.createEl("button", { cls: "sg-event-open", text: "Open chapter" }).onclick = () => io.open(row.chapter);
    }
    if (!matches.length) results.createEl("p", { text: "No assigned backgrounds match your search." });
    if (pageCount > 1) {
      const nav = results.createDiv({ cls: "sg-event-pagination" });
      const previous = nav.createEl("button", { text: "Previous" });
      previous.disabled = page === 0;
      nav.createSpan({ text: `${page + 1} / ${pageCount}`, attr: { "aria-live": "polite" } });
      const next = nav.createEl("button", { text: "Next" });
      next.disabled = page + 1 === pageCount;
      const turn = (delta) => {
        page += delta;
        render();
        c2.scrollIntoView({ block: "start" });
      };
      previous.onclick = () => turn(-1);
      next.onclick = () => turn(1);
    }
  };
  search.oninput = () => {
    query = search.value;
    page = 0;
    io.query(query);
    render();
  };
  render();
  return () => disposePage();
}

// src/study/eventBackgroundPreview.ts
init_define_SG_BUILD();
var import_obsidian15 = require("obsidian");
var EventBackgroundPreview = class extends import_obsidian15.Modal {
  constructor(app, row, photo, openChapter) {
    super(app);
    this.row = row;
    this.photo = photo;
    this.openChapter = openChapter;
  }
  generation = 0;
  onOpen() {
    this.modalEl.addClass("sg-event-preview-modal");
    this.contentEl.createEl("h2", { text: this.row.chapter });
    this.contentEl.createEl("p", { text: this.row.name });
    const controls = this.contentEl.createDiv({ cls: "sg-event-pagination" });
    const stage = this.contentEl.createDiv({ cls: "sg-event-preview-stage" });
    const show = async (wide) => {
      const generation = ++this.generation;
      stage.empty();
      const status = stage.createEl("p", { text: "Loading photo\u2026" });
      try {
        const url = await this.photo(this.row.scene, wide);
        if (generation !== this.generation) return;
        stage.empty();
        const img = stage.createEl("img", { attr: { src: url, alt: this.row.name } });
        img.onerror = () => {
          img.remove();
          stage.createEl("p", { text: "Photo unavailable. Try opening the preview again." });
        };
      } catch {
        if (generation !== this.generation) return;
        status.setText("Photo unavailable. Connect to download this background.");
        stage.createEl("button", { text: "Retry" }).onclick = () => void show(wide);
      }
      portrait.setAttribute("aria-pressed", String(!wide));
      landscape?.setAttribute("aria-pressed", String(wide));
    };
    const portrait = controls.createEl("button", { text: "Portrait" });
    portrait.onclick = () => void show(false);
    const landscape = SCENE_CATALOG[this.row.scene]?.wide ? controls.createEl("button", { text: "Landscape" }) : null;
    if (landscape) landscape.onclick = () => void show(true);
    if (this.openChapter) this.contentEl.createEl("button", { cls: "mod-cta", text: "Open chapter" }).onclick = () => {
      this.close();
      this.openChapter?.(this.row.chapter);
    };
    void show(false);
  }
  onClose() {
    this.generation++;
    this.contentEl.empty();
  }
};

